create table eba_demo_appr_appraisals (
    id                    number
        generated by default on null as identity
    not null enable,
    empno                 number not null enable,
    period_start          date,
    period_end            date,
    appraisal_date        date,
    originator            varchar2(80 byte),
    status                varchar2(15 byte) default 'ORIGINATED',
    emp_achievements      varchar2(4000 byte),
    emp_development_goals varchar2(4000 byte),
    mgr_appraisal         varchar2(4000 byte),
    mgr_objectives        varchar2(4000 byte),
    date_originated       date,
    input_completed       date,
    manager_completed     date,
    vp_review_date        date
);

alter table eba_demo_appr_appraisals
    add constraint emp_appraisal_status_ck
        check ( status in ( 'ORIGINATED', 'SUBMITTED', 'MGR_SUBMITTED', 'VP_REVIEWED', 'COMPLETED' ) ) enable;


